<script setup>
import {ref,onMounted} from 'vue';import {api} from '../api';
const props=defineProps({student:Boolean});const current=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date());const month=ref(current),board=ref(null),error=ref(''),busy=ref(false);
async function load(){busy.value=true;error.value='';try{board.value=await api((props.student?'/public/rankings/student-monthly-board':'/rankings/admin/monthly-board')+'?month='+encodeURIComponent(month.value));}catch(e){error.value=e.message;}finally{busy.value=false;}}onMounted(load);
</script>
<template><section :class="['monthly',{student}]"><header><h2>月榜与历史榜</h2><label>月份<input v-model="month" type="month" min="2000-01" max="2100-12" @change="load"></label><button :disabled="busy" @click="load">查询月榜</button></header><p v-if="error" role="alert">{{error}}</p><template v-if="board"><p>{{board.rule}}</p><p v-if="board.missingDateCount" class="warning">{{board.missingDateCount}} 个课节缺少可靠实际日期，尚未计入月榜；请联系老师补齐。</p><small>更新时间：{{board.updatedAt?new Date(board.updatedAt).toLocaleString():'暂无课程记录'}}</small><div class="scroll"><table><thead><tr><th>名次</th><th>学员</th><th>正常获得积分</th></tr></thead><tbody><tr v-for="s in board.rankings" :key="s.student_id"><td>{{s.rank}}</td><td>{{s.student_name}}</td><td>{{s.earned_points}}</td></tr></tbody></table></div><p v-if="!board.rankings.length">该月份暂无榜单数据</p></template></section></template>
<style scoped>.monthly{background:#fff;border:1px solid #d8e0e3;border-radius:10px;padding:20px;min-width:0;color:#233d47}.monthly h2{font-size:18px;margin:0}.monthly header{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.monthly label{display:flex;gap:8px;align-items:center;font-size:13px}.monthly input,.monthly button{padding:8px;border:1px solid #cedcde;border-radius:6px;min-width:0}.monthly button{background:#edf8f5;color:#16766f;cursor:pointer}.monthly p,.monthly small{color:#6b7d88;line-height:1.7}.monthly .warning{color:#9b6813}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #dfe8e9;text-align:left;white-space:nowrap}.monthly.student{background:#12213b;color:#e7f0ff;border-color:#304664}.student input,.student button{background:#1a3555;color:#b6edff;border-color:#456687}.student p,.student small{color:#adbbd4}.student .warning{color:#f0cd88}.student th,.student td{border-color:#304664}</style>
